package com.lawdesk.documents;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

/**
 * LD-055 (requirement 13, owner decision D7): what the archive reads from a file without any recognition engine. Real files
 * are generated by the tests (PDF with a text layer, scans, Word); nothing is assumed about how a producer writes Arabic.
 */
class TextExtractorTest {

    private final TextExtractor extractor = new TextExtractor();

    private TextExtractor.Result read(String mediaType, byte[] content) {
        return extractor.extract(mediaType, content, 2_000_000);
    }

    @Test
    void readsTheTextLayerOfAPdf() {
        TextExtractor.Result result = read("application/pdf", ArchiveFiles.pdfWithText("Statement of claim number 15", "second line of the claim"));
        assertThat(result.outcome()).isEqualTo(TextExtractor.Outcome.TEXT);
        assertThat(result.method()).isEqualTo("PDF_TEXT");
        assertThat(result.text()).contains("Statement of claim number 15").contains("second line");
        assertThat(result.pages()).isEqualTo(1);
    }

    @Test
    void readsArabicFromTheTextLayerOfAPdf() {
        TextExtractor.Result result = read("application/pdf", ArchiveFiles.pdfWithArabic("صحيفة الدعوى المدنية رقم 15 لسنة 2026"));
        assertThat(result.outcome()).isEqualTo(TextExtractor.Outcome.TEXT);
        assertThat(result.text()).contains("صحيفة").contains("الدعوى").contains("المدنية");
    }

    @Test
    void turnsArabicPresentationFormsIntoOrdinaryLetters() {
        // A producer that shaped the letters itself (as the system's own PDF exports do) writes presentation forms.
        String shaped = ArchiveFiles.visual("مذكرة دفاع المدعى عليه");
        assertThat(shaped).isNotEqualTo("مذكرة دفاع المدعى عليه").matches(".*[\\uFE70-\\uFEFF].*");
        TextExtractor.Result result = read("application/pdf", ArchiveFiles.pdfWithArabic("مذكرة دفاع المدعى عليه 2026"));
        assertThat(result.outcome()).isEqualTo(TextExtractor.Outcome.TEXT);
        assertThat(result.text()).contains("مذكرة").contains("دفاع").contains("المدعى");
    }

    @Test
    void aPdfWithoutATextLayerNeedsRecognition() {
        TextExtractor.Result result = read("application/pdf", ArchiveFiles.scannedPdf("scanned judgment text"));
        assertThat(result.outcome()).isEqualTo(TextExtractor.Outcome.NEEDS_OCR);
        assertThat(result.text()).isNull();
    }

    @Test
    void imagesNeedRecognition() {
        assertThat(read("image/png", ArchiveFiles.png("page")).outcome()).isEqualTo(TextExtractor.Outcome.NEEDS_OCR);
        assertThat(read("image/jpeg", ArchiveFiles.jpeg("page")).outcome()).isEqualTo(TextExtractor.Outcome.NEEDS_OCR);
        assertThat(read("image/tiff", ArchiveFiles.tiff("page")).outcome()).isEqualTo(TextExtractor.Outcome.NEEDS_OCR);
    }

    @Test
    void rendersThePagesOfAScannedPdfForRecognition() throws Exception {
        TextExtractor.PageImages pages = extractor.render(ArchiveFiles.scannedPdf("one page"), 5);
        assertThat(pages.totalPages()).isEqualTo(1);
        assertThat(pages.images()).hasSize(1);
        assertThat(pages.images().get(0)).startsWith(new byte[] {(byte) 0x89, 'P', 'N', 'G'});
    }

    @Test
    void readsTheParagraphsOfAWordDocument() {
        TextExtractor.Result result = read(FileFormats.DOCX_TYPE, ArchiveFiles.docx("مذكرة دفاع", "المادة 12 من القانون المدني & more <b>"));
        assertThat(result.outcome()).isEqualTo(TextExtractor.Outcome.TEXT);
        assertThat(result.method()).isEqualTo("DOCX");
        assertThat(result.text()).isEqualTo("مذكرة دفاع\nالمادة 12 من القانون المدني & more <b>");
    }

    @Test
    void aWordDocumentDeclaringAnExternalEntityNeverReadsTheFile() {
        TextExtractor.Result result = read(FileFormats.DOCX_TYPE, ArchiveFiles.docxWithEntity());
        assertThat(result.outcome()).isIn(TextExtractor.Outcome.FAILED, TextExtractor.Outcome.NO_TEXT);
        assertThat(result.text()).isNull();
    }

    @Test
    void anEmptyWordDocumentHasNoText() {
        assertThat(read(FileFormats.DOCX_TYPE, ArchiveFiles.docx("   ")).outcome()).isEqualTo(TextExtractor.Outcome.NO_TEXT);
    }

    @Test
    void theTextOfTheOldWordFormatIsNotReadAndSaysSo() {
        assertThat(read("application/msword", new byte[] {(byte) 0xD0, (byte) 0xCF, 0x11, (byte) 0xE0}).outcome())
                .isEqualTo(TextExtractor.Outcome.UNSUPPORTED);
    }

    @Test
    void aBrokenPdfIsReportedAsFailedNotAsEmpty() {
        assertThat(read("application/pdf", "%PDF-1.7 this is not a pdf".getBytes(StandardCharsets.ISO_8859_1)).outcome())
                .isEqualTo(TextExtractor.Outcome.FAILED);
    }

    @Test
    void longTextIsCutAtTheConfiguredSizeAndMarkedTruncated() {
        TextExtractor.Result result = extractor.extract("application/pdf", ArchiveFiles.pdfWithText("a".repeat(40) + " " + "b".repeat(40)), 30);
        assertThat(result.text()).hasSize(30);
        assertThat(result.truncated()).isTrue();
    }

    @Test
    void cleaningRemovesControlCharactersAndNulBytes() {
        assertThat(TextExtractor.clean("a\u0000b\u0007c\n\nd")).isEqualTo("a b c\n\nd");
    }
}
